import * as THREE from './three.module.js';
const $=s=>document.querySelector(s), ingredients=[['月露草','🌿','生命 · 清新',0x83aa76],['焰心莓','🍒','热情 · 活力',0xbc5955],['星尘菇','🍄','幻梦 · 神秘',0x9b85b4],['琥珀花','🌼','日光 · 温暖',0xe5b954],['霜晶石','💎','冰霜 · 澄澈',0x8ec8ce],['夜蝶粉','🦋','月夜 · 轻盈',0x909dd6]];
const recipes=[{name:'治愈药剂',emoji:'❤️',ids:[0,1],heat:1,price:45,desc:'让擦伤和坏心情一起消失。'},{name:'活力药剂',emoji:'⚡',ids:[1,3],heat:2,price:58,desc:'给漫长的一天添一点精神。'},{name:'安眠药剂',emoji:'🌙',ids:[0,2],heat:0,price:54,desc:'做一个柔软的、长长的梦。'},{name:'冰霜药剂',emoji:'❄️',ids:[0,4],heat:0,price:68,desc:'把整个夏天装进凉爽里。'},{name:'幸运药剂',emoji:'🍀',ids:[2,3,5],heat:1,price:105,desc:'下一片四叶草也许就在脚边。'},{name:'隐身药剂',emoji:'👻',ids:[2,5],heat:0,price:78,desc:'悄悄穿过落叶，不惊醒森林。'},{name:'星光药剂',emoji:'✨',ids:[3,4,5],heat:2,price:115,desc:'为迷路的旅人点亮归途。'},{name:'变形药剂',emoji:'🦊',ids:[1,2,4],heat:1,price:130,desc:'世界换个模样，魔法仍旧温柔。'}];
const fresh=()=>({day:1,gold:120,rep:0,inv:[6,5,4,3,2,2],potions:Array(8).fill(0),known:[0],upgrades:{pot:0,garden:0,sign:0},sales:0,brews:0,explored:0,harvestDay:0,quest:false,perfect:0,energy:3,orders:[0,2]});
let state;try{state=Object.assign(fresh(),JSON.parse(localStorage.getItem('foxglove-v1')||'null'));if(!Array.isArray(state.inv)||state.inv.length!==6)state=fresh()}catch{state=fresh()}
let selected=[],heat=1,muted=true,busy=false,timer,quality=1,brewTicker,fx=0;const modal=$('#modal');
function save(){try{localStorage.setItem('foxglove-v1',JSON.stringify(state))}catch{$('#save-status').textContent='存储不可用 · 本次游玩仍可继续'}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3600);tone(540)}
function tone(freq=440){if(muted)return;try{const A=window.AudioContext||window.webkitAudioContext;audio??=new A();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(.04,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.35);o.start();o.stop(audio.currentTime+.35)}catch{}}let audio;
function render(){['day','gold','rep'].forEach(id=>$('#'+id).textContent=state[id]);$('#recipe-count').textContent=state.known.length+' / 8';$('#potion-count').textContent=state.potions.reduce((a,b)=>a+b,0)+' 瓶';$('#event').textContent=['花开时节 · 今日草药采集 +1','丰收集市 · 今日订单收入 +20%','月光盈盈 · 今日探索稀有材料 +1'][(state.day-1)%3];$('#ingredients').innerHTML=ingredients.map((x,i)=>`<button class="ingredient" data-add="${i}" aria-label="加入${x[0]}"><span class="emoji">${x[1]}</span><span><strong>${x[0]}</strong><small>${x[2]}</small></span><span class="count">${state.inv[i]}</span></button>`).join('');$('#orders').innerHTML=state.orders.map((r,i)=>`<article class="order"><div class="customer"><span class="face">${i===0?'🐰':'🦉'}</span><div><strong>${i===0?'米米 · 森林邮差':'奥利 · 夜间学者'}</strong><small>${i===0?'刚从松果小径回来':'带着星星的问候'}</small></div></div><p>“${r===0?'跑得太快，脚上又多了一道擦伤。':r===2?'今晚想睡个好觉，明天再数星星。':'听说你的'+recipes[r].name+'很灵验，能为我做一瓶吗？'}”</p><div class="order-bottom"><span>${recipes[r].emoji} ${recipes[r].name}</span><button data-sell="${i}">${state.potions[r]?'交付':'准备'} · ${price(r)} ◎</button></div></article>`).join('');$('#quest-title').textContent=state.quest?'森林里的新名字':'第一瓶魔法';$('#quest-text').textContent=state.quest?'发现所有 8 种配方，让狐尾小铺成为森林传说。':'调配一瓶治愈药剂，交给森林里的朋友。';$('#quest-progress').textContent=state.quest?state.known.length+' / 8 发现配方':state.sales+' / 1 完成订单';save()}
function price(r){return Math.round(recipes[r].price*(1+state.upgrades.sign*.15)*((state.day-1)%3===1?1.2:1))}
function show(title,html,sub='FOXGLOVE · 林间炼金日记'){if(busy)return;$('#modal-title').textContent=title;$('#modal-sub').textContent=sub;$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal()}
function brewView(){show('炼金工作台',`<p class="note">选择 2–3 种药材，再试试不同的火候。手札中的配方可以直接装填。</p><div class="slots">${[0,1,2].map(i=>`<button class="slot" data-remove="${i}">${selected[i]===undefined?'+':ingredients[selected[i]][1]}<small>${selected[i]===undefined?'加入药材':ingredients[selected[i]][0]}</small></button>`).join('')}</div><div class="modal-ingredients">${ingredients.map((x,i)=>`<button data-add="${i}" ${state.inv[i]<=selected.filter(v=>v===i).length?'disabled':''}>${x[1]} ${x[0]} ×${state.inv[i]}</button>`).join('')}</div><div class="heat"><span>炉火</span>${['小火','温火','旺火'].map((x,i)=>`<button data-heat="${i}" class="${heat===i?'selected':''}">${['♧','♨','♨♨'][i]} ${x}</button>`).join('')}</div><button class="wide primary" id="start-brew" ${selected.length<2?'disabled':''}>开始调配 · ${selected.length} 种药材</button><p class="note">试验失败会获得 5 金币研究补助。药锅升级可提高产量。</p>`,'THE ALCHEMIST’S WORKBENCH')}
function add(i){if(busy)return;if(selected.length>=3){toast('炼金锅最多容纳三种药材');return}if(state.inv[i]<=selected.filter(x=>x===i).length){toast('这味药材用完了，去花园看看吧');return}selected.push(i);brewView();tone(320+i*55)}
function startBrew(){if(busy||selected.length<2)return;for(let i=0;i<6;i++)if(selected.filter(x=>x===i).length>state.inv[i])return;selected.forEach(i=>state.inv[i]--);render();const ids=[...selected].sort().join(','),found=recipes.findIndex(r=>[...r.ids].sort().join(',')===ids&&r.heat===heat);busy=true;quality=1;fx=5;$('#modal-body').innerHTML='<div class="result"><span>⚗️</span><h3>咕嘟，咕嘟……</h3><p>在指针进入深绿色区域时搅拌，获得额外金币。</p><div class="meter"><i class="needle"></i></div><button class="wide primary" id="stir">搅拌一下！</button><p class="note">不操作也会自动完成调配。</p></div>';let elapsed=0;brewTicker=setInterval(()=>{elapsed+=50;const pct=(Math.sin(elapsed/450)+1)*50;const needle=$('.needle');if(needle)needle.style.left=pct+'%';const btn=$('#stir');if(btn)btn.onclick=()=>{quality=pct>=40&&pct<=65?2:1;btn.disabled=true;btn.textContent=quality===2?'✦ 完美搅拌！':'已搅拌 · 药香正在散开';tone(quality===2?880:440)};if(elapsed>=3600){clearInterval(brewTicker);busy=false;selected=[];state.brews++;if(found<0){state.gold+=5;show('一个有趣的意外',`<div class="result"><span>🫧</span><h3>冒泡的神秘汤</h3><p>配方或火候还差一点点。获得 5 ◎ 研究补助。</p><p class="note">试试：月露草 + 星尘菇 + 小火，可以酿出安眠药剂。</p><button class="wide primary" data-action="brew">再试一次</button></div>`)}else{const isNew=!state.known.includes(found);if(isNew)state.known.push(found);let count=1+(state.upgrades.pot>0?1:0);state.potions[found]+=count;state.rep+=isNew?10:2;if(quality===2){state.perfect++;state.gold+=10}show(isNew?'✦ 新配方被发现了！':'药剂调配完成',`<div class="result"><span>${recipes[found].emoji}</span><h3>${recipes[found].name} ×${count}</h3><p>${recipes[found].desc}</p><p class="note">${isNew?'已记入配方手札 · 声望 +10':'声望 +2'}${quality===2?' · 完美搅拌奖励 10 ◎':''}</p><button class="wide primary" data-action="inventory">放上药剂架</button></div>`)}render()}},50)}
function sell(i){const r=state.orders[i];if(!state.potions[r]){toast('先调配 '+recipes[r].name+'，配方提示已放在手札中');showRecipes();return}state.potions[r]--;state.gold+=price(r);state.rep+=5;state.sales++;if(!state.quest){state.quest=true;state.gold+=50;toast('第一笔订单完成！获得 50 ◎ 额外奖励')}else toast('客人开心地带走了药剂！收入 '+price(r)+' ◎');state.orders[i]=(r+1+state.day)%recipes.length;render()}
function showRecipes(){show('配方手札',`<p class="note">已发现 ${state.known.length} / 8 · 未发现的配方也留下了研究线索。</p><div class="recipe-grid">${recipes.map((r,i)=>`<div class="recipe"><span class="big">${r.emoji}</span><h3>${r.name} ${state.known.includes(i)?'✓':'· 待研究'}</h3><p>${r.ids.map(n=>ingredients[n][0]).join(' + ')}<br>${['小火','温火','旺火'][r.heat]} · 售价 ${price(i)} ◎</p><button data-recipe="${i}">装填这份配方</button></div>`).join('')}</div>`)}
function garden(){show('药材花园',`<p>晨露挂在叶尖上，花园正等着你。</p><div class="recipe-grid">${ingredients.slice(0,4).map((x,i)=>`<div class="recipe"><span class="big">${x[1]}</span><h3>${x[0]}</h3><p>每天长出 ${2+state.upgrades.garden+((state.day-1)%3===0?1:0)} 份</p></div>`).join('')}</div><br><button class="wide primary" id="harvest" ${state.harvestDay===state.day?'disabled':''}>${state.harvestDay===state.day?'今天已经采集过了 · 明天再来':'采集成熟的药材'}</button><p class="note">霜晶石和夜蝶粉藏在森林深处。打烊进入下一天可让药材重新成熟。</p><button class="wide buy" data-action="rest">☾ 打烊，迎接新的一天</button>`)}
function harvest(){if(state.harvestDay===state.day)return;for(let i=0;i<4;i++)state.inv[i]+=2+state.upgrades.garden+((state.day-1)%3===0?1:0);state.harvestDay=state.day;render();garden();toast('挎包里装满了带着晨露的新鲜药材')}
function explore(){show('走进微光森林',`<p class="note">今日精力 ${state.energy} / 3 · 每次探索消耗 1 点精力，打烊后恢复。</p><div class="explore-options"><button data-explore="0" ${!state.energy?'disabled':''}><strong>🌲 松果小径</strong><small>寻找月露草、焰心莓和琥珀花 · 免费</small></button><button data-explore="1" ${!state.energy?'disabled':''}><strong>💎 月光洞窟</strong><small>寻找霜晶石与星尘菇 · 10 ◎</small></button><button data-explore="2" ${!state.energy?'disabled':''}><strong>🦋 萤火湖畔</strong><small>寻找夜蝶粉与琥珀花 · 15 ◎</small></button></div>`)}
function trip(n){const cost=[0,10,15][n];if(!state.energy)return;if(state.gold<cost){toast('金币不够，先交付订单或采集免费药材吧');return}state.gold-=cost;state.energy--;state.explored++;const ids=[[0,1,3],[4,2],[5,3]][n],amount=2+((state.day-1)%3===2?1:0);ids.forEach(i=>state.inv[i]+=amount);render();show('带着森林的礼物回家',`<div class="result"><span>${['🌲','💎','🦋'][n]}</span><h3>${['树梢传来松鼠的问候','你找到一簇发光的晶石','夜蝶落在你的耳尖'][n]}</h3><p>${ids.map(i=>ingredients[i][1]+' '+ingredients[i][0]+' ×'+amount).join('　')}</p><button class="wide primary" data-action="brew">带回小屋炼金</button></div>`)}
function upgrades(){show('让小店慢慢长大',`<p class="note">用每一笔小小的收入，照料心爱的小屋。</p>${[['pot','⚗️','铜制双层药锅','每次成功调配产出 2 瓶药剂',150,1],['garden','🌱','药材花园扩建','每级让每日每种药材额外生长 1 份',90,3],['sign','🏷️','手绘店铺招牌','每级让药剂售价提高 15%',100,3]].map(([key,em,name,desc,cost,max])=>`<div class="row"><div><strong>${em} ${name} · Lv.${state.upgrades[key]}</strong><p>${desc}</p></div><button class="buy" data-upgrade="${key}" ${state.upgrades[key]>=max?'disabled':''}>${state.upgrades[key]>=max?'已满级':cost*(state.upgrades[key]+1)+' ◎ 升级'}</button></div>`).join('')}<h3>小小成就</h3>${[[state.brews>=1,'初试炼金'],[state.sales>=5,'熟客的朋友'],[state.known.length>=8,'配方收藏家'],[state.perfect>=3,'炉火纯青'],[state.explored>=5,'森林漫游者']].map(([ok,x])=>`<span class="achievement">${ok?'✦':'◇'} ${x}</span>`).join('')}`)}
function upgrade(key){if(!['pot','garden','sign'].includes(key))return;const max=key==='pot'?1:3,cost=({pot:150,garden:90,sign:100}[key])*(state.upgrades[key]+1);if(state.upgrades[key]>=max)return;if(state.gold<cost){toast('还差 '+(cost-state.gold)+' 金币，再完成几笔订单吧');return}state.gold-=cost;state.upgrades[key]++;render();upgrades();toast('小店升级啦！')}
function inventory(){show('你的药剂架',`<div class="recipe-grid">${recipes.map((r,i)=>`<div class="recipe"><span class="big">${r.emoji}</span><h3>${r.name} ×${state.potions[i]}</h3><p>${r.desc}</p><button data-market="${i}" ${!state.potions[i]?'disabled':''}>摆摊出售 · ${Math.round(price(i)*.8)} ◎</button></div>`).join('')}</div><p class="note">直接摆摊售价为订单的 80%，完成客人订单还能获得声望。</p>`)}
const actions={brew:brewView,recipes:showRecipes,garden,explore,upgrades,inventory,shop:()=>{modal.close();toast('欢迎回到狐尾小屋')},rest:()=>{show('今天也辛苦了',`<div class="result"><span>🌙</span><h3>让炉火休息一会儿</h3><p>进入下一天：花园重新成熟、精力恢复，新的森林事件开始。未完成的订单会保留。</p><button class="wide primary" id="next-day">收好手札，晚安</button></div>`)},help:()=>show('欢迎，小小炼金师',`<p>你是森林中新来的小狐狸，经营着一家温暖的魔法药剂店。</p><div class="row"><span>① 采集</span><p>每天去药材花园采收，或探索森林寻找稀有材料。</p></div><div class="row"><span>② 试验</span><p>选择 2–3 种材料与火候。参考配方手札，发现八种药剂。</p></div><div class="row"><span>③ 经营</span><p>交付森林来信中的订单，赚取金币与声望，升级小店。</p></div><div class="row"><span>④ 探索</span><p>WASD / 方向键移动，E 炼金，点击锅、花园或柜台互动，滚轮缩放。手机可直接使用场景下方按钮。</p></div><p class="note">游戏自动保存于此浏览器。关闭后再回来，小狐狸还会等着你。</p>`)};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(busy&&!['stir','sound'].includes(b.id))return;if(b.dataset.action)actions[b.dataset.action]?.();if(b.dataset.add!==undefined)add(+b.dataset.add);if(b.dataset.remove!==undefined){selected.splice(+b.dataset.remove,1);brewView()}if(b.dataset.heat!==undefined){heat=+b.dataset.heat;brewView()}if(b.dataset.sell!==undefined)sell(+b.dataset.sell);if(b.dataset.recipe!==undefined){const r=recipes[+b.dataset.recipe];if(r.ids.some(i=>!state.inv[i])){toast('材料还不齐，去花园采集或探索森林吧');return}selected=[...r.ids];heat=r.heat;brewView()}if(b.dataset.explore!==undefined)trip(+b.dataset.explore);if(b.dataset.upgrade)upgrade(b.dataset.upgrade);if(b.dataset.market!==undefined){let i=+b.dataset.market;if(state.potions[i]){state.potions[i]--;state.gold+=Math.round(price(i)*.8);render();inventory();tone(660)}}if(b.id==='start-brew')startBrew();if(b.id==='harvest')harvest();if(b.id==='next-day'){state.day++;state.energy=3;selected=[];render();modal.close();toast('早安！花园的药材成熟了，新的冒险开始了')}if(b.id==='close')modal.close();if(b.id==='sound'){muted=!muted;b.textContent=muted?'♫':'♪';b.title=muted?'音效已关闭':'音效已开启';tone(600)}});
modal.addEventListener('cancel',e=>{if(busy)e.preventDefault()});render();
