const scene=new THREE.Scene();scene.background=new THREE.Color(0xe7eadc);scene.fog=new THREE.Fog(0xe7eadc,24,65);const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;$('#world').appendChild(renderer.domElement);const camera=new THREE.OrthographicCamera(-12,12,9,-9,.1,100);camera.position.set(15,17,21);camera.lookAt(0,.3,0);scene.add(new THREE.HemisphereLight(0xfff5da,0x899976,2.6));const sun=new THREE.DirectionalLight(0xffe5b2,4);sun.position.set(-9,18,9);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-16,right:16,top:16,bottom:-16});sun.shadow.normalBias=.035;scene.add(sun);
const mat=c=>new THREE.MeshStandardMaterial({color:c,roughness:.86,flatShading:true});const mats={wood:mat(0x76533b),dark:mat(0x503c2d),plank:mat(0xb48e61),wall:mat(0xd7c5a0),leaf:mat(0x738c53),stone:mat(0x9ca592),orange:mat(0xce7842),cream:mat(0xffe3b5),black:mat(0x35392e)};
function mesh(g,m,x,y,z,parent=scene){const a=new THREE.Mesh(g,typeof m==='number'?mat(m):m);a.position.set(x,y,z);a.castShadow=true;a.receiveShadow=true;parent.add(a);return a}function box(w,h,d,m,x,y,z,p){return mesh(new THREE.BoxGeometry(w,h,d),m,x,y,z,p)}function sphere(r,m,x,y,z,p,seg=8){return mesh(new THREE.SphereGeometry(r,seg,6),m,x,y,z,p)}function cyl(rt,rb,h,m,x,y,z,p,seg=10){return mesh(new THREE.CylinderGeometry(rt,rb,h,seg),m,x,y,z,p)}function cone(r,h,m,x,y,z,p){return mesh(new THREE.ConeGeometry(r,h,7),m,x,y,z,p)}
const ground=cyl(10,10.6,.65,0xb3bea0,0,-.65,0,scene,14);box(200,.1,200,0xe0e5d5,0,-1.04,0);cyl(10.08,10.15,.15,0xcbd0b0,0,-.27,0,scene,14);
