box(8.4,.45,6.5,mats.dark,-.1,0,-.7);for(let i=0;i<17;i++)box(.465,.12,6.3,i%3===0?0xc39d6b:0xb99466,-4+i*.485,.29,-.7);box(8.4,3.5,.22,mats.wall,-.1,2.05,-3.9);box(.24,3.5,6.5,mats.wall,-4.2,2.05,-.7);[-4.1,-.1,4].forEach(x=>box(.22,4.1,.32,mats.dark,x,2.15,-3.75));[-3.8,-.6,2.4].forEach(z=>box(.32,4.1,.22,mats.dark,-4.05,2.15,z));box(8.5,.24,.35,mats.dark,-.1,4.15,-3.8);box(.35,.24,6.6,mats.dark,-4.05,4.15,-.7);box(8.2,.16,.2,mats.wood,-.1,.75,-3.7);box(.2,.16,6,mats.wood,-3.9,.75,-.7);
